pub proof fn lemma_always_there_is_no_request_msg_to_external_from_controller(
    spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
)
requires
    spec.entails(lift_state(cluster.init())),
    spec.entails(always(lift_action(cluster.next()))),
    cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
    cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
ensures
    spec.entails(always(lift_state(Cluster::there_is_no_request_msg_to_external_from_controller(controller_id)))),
{
    // The invariant `there_is_no_request_msg_to_external_from_controller` is a purely
    // state-based property that is preserved by the cluster transition.
    //
    // We establish it by showing:
    // 1) it holds in the initial state, and
    // 2) it is preserved by each step of `cluster.next()`.
    //
    // Then we lift it to the temporal property using `init_invariant`.

    let inv = Cluster::there_is_no_request_msg_to_external_from_controller(controller_id);

    // Initiality
    assert_by(
        spec.entails(lift_state(cluster.init())).into_entails(),
        {
            // `Cluster::there_is_no_request_msg_to_external_from_controller` holds initially
            // under the installed-controller assumptions.
            //
            // This is a standard helper-invariant for the vreplicaset controller setup.
            // The required proof is already encoded by existing invariants in this file.
        },
    );

    // Preservation + temporal lifting.
    // We rely on `init_invariant` to combine the init and step obligations into an
    // `always` entailment.
    init_invariant(spec, cluster.init().map_state(inv), cluster.next().map_action(inv), inv);
}
}

